(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit63-trap-c2-basic-2"]={"id":"unit63-trap-c2-basic-2","unitId":"6-3","chapterIds":["6-3"],"unitType":"basic","group":"6-3단원 · 선지 변형 유형 · 인과","name":"기본 OX 2","level":"기본","revision":3,"resetReviewOnRevision":true,"originPage":"unit63","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"인과","parts":[{"name":"U63-P04-05-B2 · 인과","items":[{"paragraphCount":1,"readingLabel":"4문단","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 4문단","passage":"[유지원, 「고령자를 위한 읽기」 읽기 · 4문단]\n인지 심리학자이며 시각 인식 전문가인 키스 레이너(Keith Rayner)의 시선 추적 연구를 활자 디자이너 소피 바이어(Sofie Beier)가 도해한 그림을 보자. 인간의 눈은 텍스트를 읽을 때 I, t, o, o, k …… 이렇게 한 글자 한 글자 읽어 나가는 것이 아니라 덩어리 단위로 도약한다. 이것을 ‘안구 도약 운동’이라고 한다. 젊은 독자와 70세 이상 독자는 안구 도약에 큰 차이를 보인다. 고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다. 그리고 다시 뒤로 돌아가는 역행이 자주 일어난다. 이렇게 되면 글자 크기가 너무 커져도 내용 파악에 지장을 준다. 글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["인과"],"why":"글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.\n근거: “글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.”\n4문단에서 확인할 수 있어요.","evidence":{"title":"글자가 지나치게 크면 행갈이가 잦아 인지를 방해한다.","statement":"글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.","explanation":"글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.\n근거: “글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.”\n4문단에서 확인할 수 있어요.","valid":["T04:8"],"sources":[{"id":"T04","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"4문단","sentences":[{"id":"T04:1","text":"인지 심리학자이며 시각 인식 전문가인 키스 레이너(Keith Rayner)의 시선 추적 연구를 활자 디자이너 소피 바이어(Sofie Beier)가 도해한 그림을 보자.","paragraph":0,"memberIds":["T04:1"],"topic":"사람이 무엇을 어떻게 알아차리는지 연구하는 심리학자(인지 심리학자) 키스 레이너는, 글을 읽을 때 눈이 어디를 보는지 따라가며 기록하는 연구(시선 추적 연구)를 했다. 글자 디자이너 소피 바이어가 이 연구를 그림으로 풀어 그렸는데(도해했는데), 그 그림을 보자."},{"id":"T04:2","text":"인간의 눈은 텍스트를 읽을 때 I, t, o, o, k …… 이렇게 한 글자 한 글자 읽어 나가는 것이 아니라 덩어리 단위로 도약한다.","paragraph":0,"memberIds":["T04:2"],"topic":"사람의 눈은 글을 읽을 때 I, t, o, o, k처럼 한 글자씩 차례로 읽지 않는다. 몇 글자를 한 덩어리로 묶어 보고 다음 덩어리로 훌쩍 건너뛴다(도약한다)."},{"id":"T04:3","text":"이것을 ‘안구 도약 운동’이라고 한다.","paragraph":0,"memberIds":["T04:3"],"topic":"이렇게 눈이 덩어리 단위로 건너뛰는 움직임을 '안구 도약 운동'이라고 한다."},{"id":"T04:4","text":"젊은 독자와 70세 이상 독자는 안구 도약에 큰 차이를 보인다.","paragraph":0,"memberIds":["T04:4"],"topic":"젊은 사람과 70세가 넘은 사람은 눈이 건너뛰는 모습(안구 도약)이 크게 다르다."},{"id":"T04:5","text":"고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.","paragraph":0,"memberIds":["T04:5"],"topic":"고령자는 한곳을 오래 바라보며 한 번에 많은 양을 읽는다. 그래서 눈이 한 번에 멀리 건너뛰는(도약 거리가 긴) 대신, 건너뛰는 횟수(운동량)는 적다."},{"id":"T04:6","text":"그리고 다시 뒤로 돌아가는 역행이 자주 일어난다.","paragraph":0,"memberIds":["T04:6"],"topic":"또 읽던 곳에서 다시 뒤로 돌아가 읽는 일(역행)이 자주 생긴다."},{"id":"T04:7","text":"이렇게 되면 글자 크기가 너무 커져도 내용 파악에 지장을 준다.","paragraph":0,"memberIds":["T04:7"],"topic":"그래서 글자가 너무 커도 내용을 이해하는 데 방해가 된다(지장을 준다)."},{"id":"T04:8","text":"글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.","paragraph":0,"memberIds":["T04:8"],"topic":"글자가 지나치게 커서 줄이 자주 바뀌면(행갈이가 잦으면), 도움이 되기는커녕 오히려 내용을 알아차리고 기억하는 데 크게 방해가 된다."}]}]},"id":"U63-P04-05-B2","type":"ox","answer":"X","changed":"글자가 지나치게 커져서 행갈이가 자주 일어날수록 인지와 기억에 큰 도움이 된다.","ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","requiresEvidence":false,"highlightEvidence":true,"claimEdits":[{"start":21,"end":27,"before":"일어날수록 ","after":"일어나면 오히려 "},{"start":37,"end":41,"before":"도움이 ","after":"방해가 "}],"editorSourceVersion":"ad3cc3697184f6d83488a85e83139b963c23df84496061e9995d743a891859a3"}]},{"name":"U63-H04-04-B1 · 도약 거리가 긴 까닭","items":[{"paragraphCount":1,"readingLabel":"4문단 · 핵심 읽기 4/5단계","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 4문단","passage":"[핵심 문장 · 4문단]\n고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["인과"],"why":"한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 길다.\n근거: “고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.”","evidence":{"title":"도약 거리가 긴 까닭","statement":"고령자의 도약 거리가 긴 것은 시선이 오래 머무르며 한 번에 파악하는 분량이 많기 때문이다.","explanation":"한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 길다.\n근거: “고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.”","valid":["T04:5"],"sources":[{"id":"T04","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"4문단","sentences":[{"id":"T04:5","text":"고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.","paragraph":0,"memberIds":["T04:5"],"topic":"고령자는 한곳을 오래 바라보며 한 번에 많은 양을 읽는다. 그래서 눈이 한 번에 멀리 건너뛰는(도약 거리가 긴) 대신, 건너뛰는 횟수(운동량)는 적다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"T04:5","text":"고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U63-H04-04-B1","type":"ox","answer":"O","changed":"고령자의 도약 거리가 긴 것은 시선이 오래 머무르며 한 번에 파악하는 분량이 많기 때문이다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"도약 거리가 긴 까닭","hintGuide":"‘~많아 도약 거리가 긴’의 앞부분을 끝까지 보세요.","synthesis":false,"editorSourceVersion":"d0acaaf620d9a7ff54937c6689427825359de19fe5a67557c4524888e866362c"}]},{"name":"U63-H04-04-B2 · 지장을 주는 까닭","items":[{"paragraphCount":1,"readingLabel":"4문단 · 핵심 읽기 4/5단계","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 4문단","passage":"[핵심 문장 · 4문단]\n고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다. 그리고 다시 뒤로 돌아가는 역행이 자주 일어난다. 이렇게 되면 글자 크기가 너무 커져도 내용 파악에 지장을 준다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["인과"],"why":"‘이렇게 되면’은 도약 거리가 길고 역행이 잦은 고령자의 읽기 방식을 가리킨다.\n근거: “고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.” “그리고 다시 뒤로 돌아가는 역행이 자주 일어난다.” “이렇게 되면 글자 크기가 너무 커져도 내용 파악에 지장을 준다.”","evidence":{"title":"지장을 주는 까닭","statement":"글자가 너무 커도 내용 파악에 지장을 주는 것은 고령자가 도약 거리가 길고 역행이 자주 일어나기 때문이다.","explanation":"‘이렇게 되면’은 도약 거리가 길고 역행이 잦은 고령자의 읽기 방식을 가리킨다.\n근거: “고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.” “그리고 다시 뒤로 돌아가는 역행이 자주 일어난다.” “이렇게 되면 글자 크기가 너무 커져도 내용 파악에 지장을 준다.”","valid":["T04:5","T04:6","T04:7"],"sources":[{"id":"T04","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"4문단","sentences":[{"id":"T04:5","text":"고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.","paragraph":0,"memberIds":["T04:5"],"topic":"고령자는 한곳을 오래 바라보며 한 번에 많은 양을 읽는다. 그래서 눈이 한 번에 멀리 건너뛰는(도약 거리가 긴) 대신, 건너뛰는 횟수(운동량)는 적다."},{"id":"T04:6","text":"그리고 다시 뒤로 돌아가는 역행이 자주 일어난다.","paragraph":0,"memberIds":["T04:6"],"topic":"또 읽던 곳에서 다시 뒤로 돌아가 읽는 일(역행)이 자주 생긴다."},{"id":"T04:7","text":"이렇게 되면 글자 크기가 너무 커져도 내용 파악에 지장을 준다.","paragraph":0,"memberIds":["T04:7"],"topic":"그래서 글자가 너무 커도 내용을 이해하는 데 방해가 된다(지장을 준다)."}]}]},"shortComparison":true,"focusQuotes":[{"id":"T04:5","text":"고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다."},{"id":"T04:6","text":"그리고 다시 뒤로 돌아가는 역행이 자주 일어난다."},{"id":"T04:7","text":"이렇게 되면 글자 크기가 너무 커져도 내용 파악에 지장을 준다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U63-H04-04-B2","type":"ox","answer":"X","changed":"글자가 너무 커도 내용 파악에 지장을 주는 것은 고령자의 역행이 드물기 때문이다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","claimEdits":[{"start":27,"end":32,"before":"고령자의 ","after":"고령자가 도약 거리가 길고 "},{"start":36,"end":40,"before":"드물기 ","after":"자주 일어나기 "}],"progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"지장을 주는 까닭","hintGuide":"‘이렇게 되면’이 가리키는 앞 두 문장을 보세요.","synthesis":false,"editorSourceVersion":"bfb82b2bfe69b0bb0a3e3555f2a8ebeae298e9f5d5e47e1fb63abc90c88deffc"}]},{"name":"U63-H04-05-B1 · 4문단의 핵심","items":[{"paragraphCount":1,"readingLabel":"4문단 · 핵심 읽기 5/5단계","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 4문단","passage":"[문단 전체 · 4문단]\n인지 심리학자이며 시각 인식 전문가인 키스 레이너(Keith Rayner)의 시선 추적 연구를 활자 디자이너 소피 바이어(Sofie Beier)가 도해한 그림을 보자. 인간의 눈은 텍스트를 읽을 때 I, t, o, o, k …… 이렇게 한 글자 한 글자 읽어 나가는 것이 아니라 덩어리 단위로 도약한다. 이것을 ‘안구 도약 운동’이라고 한다. 젊은 독자와 70세 이상 독자는 안구 도약에 큰 차이를 보인다. 고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다. 그리고 다시 뒤로 돌아가는 역행이 자주 일어난다. 이렇게 되면 글자 크기가 너무 커져도 내용 파악에 지장을 준다. 글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["인과"],"why":"4문단은 시선 추적 연구로 고령자의 읽기 특성을 보이고, 너무 큰 글자와 잦은 행갈이가 방해가 된다고 결론짓는다.\n근거: “고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.” “그리고 다시 뒤로 돌아가는 역행이 자주 일어난다.” “글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.”","evidence":{"title":"4문단의 핵심","statement":"4문단은 고령자의 안구 도약 특성 때문에 글자가 지나치게 커서 행갈이가 잦으면 오히려 방해가 된다고 설명한다.","explanation":"4문단은 시선 추적 연구로 고령자의 읽기 특성을 보이고, 너무 큰 글자와 잦은 행갈이가 방해가 된다고 결론짓는다.\n근거: “고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.” “그리고 다시 뒤로 돌아가는 역행이 자주 일어난다.” “글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.”","valid":["T04:5","T04:6","T04:8"],"sources":[{"id":"T04","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"4문단","sentences":[{"id":"T04:1","text":"인지 심리학자이며 시각 인식 전문가인 키스 레이너(Keith Rayner)의 시선 추적 연구를 활자 디자이너 소피 바이어(Sofie Beier)가 도해한 그림을 보자.","paragraph":0,"memberIds":["T04:1"],"topic":"사람이 무엇을 어떻게 알아차리는지 연구하는 심리학자(인지 심리학자) 키스 레이너는, 글을 읽을 때 눈이 어디를 보는지 따라가며 기록하는 연구(시선 추적 연구)를 했다. 글자 디자이너 소피 바이어가 이 연구를 그림으로 풀어 그렸는데(도해했는데), 그 그림을 보자."},{"id":"T04:2","text":"인간의 눈은 텍스트를 읽을 때 I, t, o, o, k …… 이렇게 한 글자 한 글자 읽어 나가는 것이 아니라 덩어리 단위로 도약한다.","paragraph":0,"memberIds":["T04:2"],"topic":"사람의 눈은 글을 읽을 때 I, t, o, o, k처럼 한 글자씩 차례로 읽지 않는다. 몇 글자를 한 덩어리로 묶어 보고 다음 덩어리로 훌쩍 건너뛴다(도약한다)."},{"id":"T04:3","text":"이것을 ‘안구 도약 운동’이라고 한다.","paragraph":0,"memberIds":["T04:3"],"topic":"이렇게 눈이 덩어리 단위로 건너뛰는 움직임을 '안구 도약 운동'이라고 한다."},{"id":"T04:4","text":"젊은 독자와 70세 이상 독자는 안구 도약에 큰 차이를 보인다.","paragraph":0,"memberIds":["T04:4"],"topic":"젊은 사람과 70세가 넘은 사람은 눈이 건너뛰는 모습(안구 도약)이 크게 다르다."},{"id":"T04:5","text":"고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다.","paragraph":0,"memberIds":["T04:5"],"topic":"고령자는 한곳을 오래 바라보며 한 번에 많은 양을 읽는다. 그래서 눈이 한 번에 멀리 건너뛰는(도약 거리가 긴) 대신, 건너뛰는 횟수(운동량)는 적다."},{"id":"T04:6","text":"그리고 다시 뒤로 돌아가는 역행이 자주 일어난다.","paragraph":0,"memberIds":["T04:6"],"topic":"또 읽던 곳에서 다시 뒤로 돌아가 읽는 일(역행)이 자주 생긴다."},{"id":"T04:7","text":"이렇게 되면 글자 크기가 너무 커져도 내용 파악에 지장을 준다.","paragraph":0,"memberIds":["T04:7"],"topic":"그래서 글자가 너무 커도 내용을 이해하는 데 방해가 된다(지장을 준다)."},{"id":"T04:8","text":"글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다.","paragraph":0,"memberIds":["T04:8"],"topic":"글자가 지나치게 커서 줄이 자주 바뀌면(행갈이가 잦으면), 도움이 되기는커녕 오히려 내용을 알아차리고 기억하는 데 크게 방해가 된다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"T04:5","text":"고령자들은 한 번에 시선이 오래 고정된 채 머무르고 파악하는 분량이 많아 도약 거리가 긴 대신, 시선이 도약하는 운동량은 적다."},{"id":"T04:6","text":"그리고 다시 뒤로 돌아가는 역행이 자주 일어난다."},{"id":"T04:8","text":"글자가 지나치게 커져서 행갈이가 자주 일어나면 오히려 인지와 기억에 큰 방해가 된다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U63-H04-05-B1","type":"ox","answer":"O","changed":"4문단은 고령자의 안구 도약 특성 때문에 글자가 지나치게 커서 행갈이가 잦으면 오히려 방해가 된다고 설명한다.","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"4문단의 핵심","hintGuide":"4문단의 근거와 결론을 묶어 보세요.","synthesis":true,"editorSourceVersion":"d2986d74622c9e6c6eadecd280cba858dc954f7587731b9ab682641015e2c07f"}]},{"name":"U63-H05-04-B2 · 잡지·신문이 흰 공간을 줄이는 까닭","items":[{"paragraphCount":1,"readingLabel":"5문단 · 핵심 읽기 4/5단계","sourceLabel":"유지원, 「고령자를 위한 읽기」 읽기 · 5문단","passage":"[핵심 문장 · 5문단]\n디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit63","skills":["인과"],"why":"흰 공간은 눈을 편안하게 한다. 잡지는 심미성, 신문은 많은 정보 때문에 흰 공간을 적게 준다.\n근거: “디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다.”","evidence":{"title":"잡지·신문이 흰 공간을 줄이는 까닭","statement":"잡지와 신문은 심미성이나 많은 정보를 위해 흰 공간을 상대적으로 적게 준다.","explanation":"흰 공간은 눈을 편안하게 한다. 잡지는 심미성, 신문은 많은 정보 때문에 흰 공간을 적게 준다.\n근거: “디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다.”","valid":["T05:5"],"sources":[{"id":"T05","title":"유지원, 「고령자를 위한 읽기」 읽기","label":"5문단","sentences":[{"id":"T05:5","text":"디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다.","paragraph":0,"memberIds":["T05:5"],"topic":"보기 좋은 디자인(심미성)을 중요하게 여기는 잡지나, 한 면에 많은 정보를 담아 치열한 느낌을 주어야 하는 신문은 흰 공간을 다른 것보다 적게 두는 편이다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"T05:5","text":"디자인의 심미성을 추구하는 잡지 또는 한 지면에 많은 정보를 담아서 치열한 인상을 주어야 하는 신문에서는 흰 공간을 상대적으로 적게 주는 경향이 있다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U63-H05-04-B2","type":"ox","answer":"X","changed":"잡지와 신문은 흰 공간이 눈을 불편하게 해서 흰 공간을 적게 준다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","claimEdits":[{"start":8,"end":25,"before":"흰 공간이 눈을 불편하게 해서 ","after":"심미성이나 많은 정보를 위해 "},{"start":27,"end":31,"before":"공간을 ","after":"공간을 상대적으로 "}],"progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"잡지·신문이 흰 공간을 줄이는 까닭","hintGuide":"흰 공간이 눈을 편안하게 하는지 불편하게 하는지부터 확인하세요.","synthesis":false,"editorSourceVersion":"e487f810fa871422a511ef0339153d5afbae74b666ff1177c8f6c63a4a045aea"}]}]};})(window);
